<?php $root=base_url('store/'.$settings->store_slug); ?>
<main class="sf-editorial"><?php if($journal_post): ?><article class="sf-journal-body"><a href="<?= $root.'/blog'; ?>">← <?= htmlspecialchars($site_content['blog_label']); ?></a><p class="sf-editorial-kicker"><time datetime="<?= htmlspecialchars(substr($journal_post->published_at,0,10)); ?>"><?= date('j F Y',strtotime($journal_post->published_at)); ?></time></p><h1><?= htmlspecialchars($journal_post->title); ?></h1><?php if($journal_post->excerpt): ?><p class="sf-editorial-intro"><?= htmlspecialchars($journal_post->excerpt); ?></p><?php endif; ?><?php if($journal_post->image_url): ?><img src="<?= htmlspecialchars($journal_post->image_url,ENT_QUOTES); ?>" alt="<?= htmlspecialchars($journal_post->title,ENT_QUOTES); ?>"><?php endif; ?><div class="sf-journal-copy"><?= htmlspecialchars($journal_post->body); ?></div></article><?php else: ?><a href="<?= $root; ?>">← Back to the store</a><p class="sf-editorial-kicker"><?= htmlspecialchars($site_content['blog_label']); ?></p><h1><?= htmlspecialchars($site_content['blog_heading']); ?></h1><p class="sf-editorial-intro"><?= htmlspecialchars($site_content['blog_intro']); ?></p><div class="sf-journal-grid"><?php foreach(array_slice($journal_posts,0,12) as $post): ?><article class="sf-journal-card"><a href="<?= $root.'/blog/'.rawurlencode($post->slug); ?>"><?php if($post->image_url): ?><img src="<?= htmlspecialchars($post->image_url,ENT_QUOTES); ?>" alt="<?= htmlspecialchars($post->title,ENT_QUOTES); ?>" loading="lazy"><?php endif; ?><p class="sf-editorial-kicker"><?= date('j F Y',strtotime($post->published_at)); ?></p><h2><?= htmlspecialchars($post->title); ?></h2><p><?= htmlspecialchars($post->excerpt ?: mb_substr($post->body,0,180)); ?></p><span>Read the story ↗</span></a></article><?php endforeach; ?></div><?php if(!$journal_posts): ?><p>Fresh stories are on their way. Come back soon.</p><?php endif; ?><nav class="sf-page-nav" aria-label="Journal pages"><?php if($journal_page>1): ?><a href="<?= $root.'/blog?page='.($journal_page-1); ?>">← Previous</a><?php endif; ?><?php if(count($journal_posts)>12): ?><a href="<?= $root.'/blog?page='.($journal_page+1); ?>">More stories →</a><?php endif; ?></nav><?php endif; ?></main>
